function countHomogenous(s) {
  const MOD = 1000000007;
  let total = 0;
  let start = 0;
  for (let i = 1; i <= s.length; i++) {
    if (i === s.length || s[i] !== s[start]) {
      const run = i - start;
      total = (total + (run * (run + 1)) / 2) % MOD;
      start = i;
    }
  }
  return total;
}

