function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alpha = 1 + Math.floor(rand() * 3);
  const length = size === 'large' ? 8000 + Math.floor(rand() * 2001) : 1 + Math.floor(rand() * 12);
  const longest = size === 'large' ? (rand() < 0.3 ? length : 1 + Math.floor(rand() * 300)) : 1 + Math.floor(rand() * 5);
  let s = '';
  while (s.length < length) {
    const run = Math.min(length - s.length, 1 + Math.floor(rand() * longest));
    s += letters[Math.floor(rand() * alpha)].repeat(run);
  }
  return [s];
}
